import{_ as e,o,c as a,a2 as d}from"./chunks/framework.Dxeykp0S.js";const f=JSON.parse('{"title":"Day 1 · 语法速览：写出第一行 Python","description":"","frontmatter":{},"headers":[],"relativePath":"novice/01-syntax.md","filePath":"novice/01-syntax.md","lastUpdated":1787141678000}'),r={name:"novice/01-syntax.md"};function l(c,t,n,i,h,s){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="day-1-·-语法速览-写出第一行-python" tabindex="-1">Day 1 · 语法速览：写出第一行 Python <a class="header-anchor" href="#day-1-·-语法速览-写出第一行-python" aria-label="Permalink to &quot;Day 1 · 语法速览：写出第一行 Python&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>今天我们系统走一遍 Python 的基础语法，一边理解，一边建立手感。其中的重点是<strong>字符串</strong>和<strong>切片</strong>，它们是 Python 日常开发中出现频率最高的操作之一。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>掌握数字、字符串、布尔值的基本操作</li><li>熟练掌握 f-string 与切片（slice）</li><li>掌握 <code>if</code> / <code>for</code> / <code>while</code> / <code>match</code> 控制流</li><li>理解 <code>for...else</code> 的执行条件与适用场景</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/tutorial/introduction.html" target="_blank" rel="noreferrer">Python 官方教程第 3 章：Python 的非正式介绍</a></li><li><a href="https://docs.python.org/zh-cn/3/tutorial/controlflow.html" target="_blank" rel="noreferrer">Python 官方教程第 4 章：流程控制</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>JavaScript</th><th>Python</th></tr></thead><tbody><tr><td>字符串重复</td><td><code>&#39;ab&#39;.repeat(3)</code></td><td><code>&#39;ab&#39; * 3</code></td></tr><tr><td>切片</td><td><code>arr.slice(1, 3)</code></td><td><code>arr[1:3]</code>（字符串也能切！）</td></tr><tr><td>倒序</td><td><code>[...arr].reverse()</code></td><td><code>arr[::-1]</code></td></tr><tr><td>遍历索引</td><td><code>arr.forEach((v, i) =&gt; ...)</code></td><td><code>for i, v in enumerate(arr):</code></td></tr><tr><td>三元表达式</td><td><code>cond ? a : b</code></td><td><code>a if cond else b</code></td></tr><tr><td>switch</td><td><code>switch/case</code></td><td><code>match/case</code>（3.10+，支持结构化模式匹配）</td></tr><tr><td>字符串格式化</td><td>模板字符串</td><td>f-string（还能写 <code>f&quot;{x=}&quot;</code> 调试）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><p>创建一个 <code>day01/</code> 目录，完成以下小练习（每个练习一个函数，最后用 <code>if __name__ == &quot;__main__&quot;:</code> 统一调用——先照抄即可，这个惯用法的原理会在 <a href="./04-modules">Day 4</a> 详细讲解）：</p><ol><li><strong>FizzBuzz</strong>：经典热身，要求用 f-string 输出，且能处理任意上限</li><li><strong>回文判断</strong>：<code>is_palindrome(&quot;上海自来水来自海上&quot;)</code>，要求用切片一行解决</li><li><strong>字符串体操</strong>：实现 <code>snake_to_camel(&quot;hello_world_foo&quot;)</code> → <code>&quot;helloWorldFoo&quot;</code> 和反向转换 <code>camel_to_snake</code>（写正则和不用正则两个版本）</li><li><strong>数字黑洞</strong>：实现 Collatz 序列（偶数除 2，奇数乘 3 加 1），输出从任意正整数到 1 的完整路径</li><li><strong>match 尝鲜</strong>：用 <code>match/case</code> 写一个迷你命令路由器，能处理 <code>(&quot;create&quot;, name)</code>、<code>(&quot;delete&quot;, name)</code>、<code>(&quot;list&quot;,)</code> 三种元组命令，体验 Python 结构化模式匹配如何同时完成解构与分支</li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li><code>s[::-1]</code> 返回的是新对象还是原地修改？Python 字符串是可变的吗？</li><li><code>for...else</code> 的 <code>else</code> 什么时候执行？它在什么场景下有用？（提示：搜索找元素）</li><li>Python 的除法 <code>7 / 2</code> 和整除 <code>7 // 2</code> 分别得到什么？</li><li>f-string 里能写表达式和函数调用吗？<code>f&quot;{x=}&quot;</code> 这个调试技巧输出什么？</li><li><code>range(10)</code> 是列表吗？它何时生成其中的数字？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记（日期、用时、目标达成情况、透彻的点、待深入的点、疑问）。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://peps.python.org/pep-0636/" target="_blank" rel="noreferrer">PEP 636：结构模式匹配教程</a></li><li><a href="https://realpython.com/python-f-strings/" target="_blank" rel="noreferrer">Python f-string 的 73 个技巧</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节学习<a href="./02-data-structures">四大数据结构</a>，以及 Python 最具代表性的语法糖——推导式。</p>',19)])])}const _=e(r,[["render",l]]);export{f as __pageData,_ as default};
